// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testRegression_property() public {
        Rejector rejector = new Rejector();
        vm.deal(address(c), 1 wei);
        bool ok;
        try c.withdrawAll(address(rejector)) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "Reference should revert when sending to a contract that rejects transfers");
    }
}

contract Rejector {
    receive() external payable {
        revert("I reject ETH");
    }
    fallback() external payable {
        revert("I reject ETH");
    }
}
